def mat(name,h,rough=.45,metal=0,emission=0):
    h=h.lstrip('#'); rgb=[int(h[i:i+2],16)/255 for i in (0,2,4)]
    lin=[v/12.92 if v<.04045 else ((v+.055)/1.055)**2.4 for v in rgb]
    m=bpy.data.materials.new(name); m.diffuse_color=(*lin,1); m.use_nodes=True
    bs=m.node_tree.nodes.get('Principled BSDF'); bs.inputs['Base Color'].default_value=(*lin,1); bs.inputs['Roughness'].default_value=rough; bs.inputs['Metallic'].default_value=metal
    if emission: bs.inputs['Emission Color'].default_value=(*lin,1); bs.inputs['Emission Strength'].default_value=emission
    return m
